import type { ItemType } from '../decks/types';
import type { Band, Criterion, ErrorCategory, TargetLevel, TaskNo } from './config';

/** A VSTEP writing prompt, generated by the AI or pasted by the player. */
export interface WritingPrompt {
  task: TaskNo;
  title: string;
  /** The full task text as the candidate reads it (English). */
  text: string;
  /** Topic id from config, or "custom" for pasted prompts. */
  topic: string;
  /** Task 2 essay type id ("" when unknown or Task 1). */
  essayType: string;
  /** Task 1: the points the letter must cover. */
  requirements: string[];
  /** Task 1: "formal" | "informal" | "semi-formal"; "" for essays. */
  register: string;
  source: 'ai' | 'custom';
}

export interface CriterionResult {
  score: number;
  comment: string;
  evidence: string[];
}

export type Severity = 'minor' | 'major';

export interface WritingError {
  quote: string;
  occurrence: number;
  category: ErrorCategory;
  rule: string;
  severity: Severity;
  correction: string;
  explanationVi: string;
}

export interface UsefulPhrase {
  text: string;
  type: ItemType;
  meaningVi: string;
  example: string;
}

/** What /api/writing/grade returns (scores recomputed on the server from the criteria). */
export interface GradeResult {
  task: TaskNo;
  level: TargetLevel;
  wordCount: number;
  minWords: number;
  criteria: Record<Criterion, CriterionResult>;
  taskScore: number;
  band: Band;
  /** The essay was shorter than required and task fulfilment was capped. */
  shortPenalty: boolean;
  errors: WritingError[];
  strengths: string[];
  improvements: string[];
  /** null when the rewrite call failed (rewriteError says why). */
  rewrite: string | null;
  rewriteError?: string;
  /** Set when the list of mistakes could not be produced in time (scores are still valid). */
  errorsError?: string;
  usefulPhrases: UsefulPhrase[];
  model: string;
  gradedAt: string;
}

export interface GradeInput {
  task: TaskNo;
  level: TargetLevel;
  prompt: WritingPrompt;
  essay: string;
  durationSec: number;
  examId?: string;
}

/** One graded attempt as stored (Cosmos "writings" or IndexedDB). */
export interface WritingRecord {
  id: string;
  task: TaskNo;
  level: TargetLevel;
  topic: string;
  prompt: WritingPrompt;
  promptId: string;
  attempt: number;
  examId?: string;
  text: string;
  wordCount: number;
  durationSec: number;
  result: GradeResult;
  createdAt: string;
}

export interface ErrorCounts {
  categories: Partial<Record<ErrorCategory, number>>;
  rules: Record<string, number>;
}

/** History row: enough for lists, charts and attempt comparison without loading the essay. */
export interface WritingSummary {
  id: string;
  task: TaskNo;
  level: TargetLevel;
  topic: string;
  title: string;
  promptId: string;
  attempt: number;
  examId?: string;
  wordCount: number;
  durationSec: number;
  createdAt: string;
  taskScore: number;
  band: Band;
  criteria: Record<Criterion, number>;
  errorCounts: ErrorCounts;
}

/** Running totals of mistakes, for a future weak-points dashboard. */
export interface WritingStats extends ErrorCounts {
  writings: number;
}

/** The server saved the attempt (signed in); otherwise the client stores it locally. */
export interface GradeResponse {
  result: GradeResult;
  saved?: { id: string; promptId: string; attempt: number };
}
